-- Backend Engineering ("The Fracture") Act 24 -- "Resilience Engineering" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 (20260810040000_backend_act1_content.sql)
-- and Act 15 (20260810190000_backend_act15_content.sql).
-- References world-be-24, whose narrative metadata was pre-authored in
-- 20260810260000_backend_acts21_25_and_arc5.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be24', 'world-be-24', 'resilience-engineering', '24A - Resilience Engineering', 'A newly-extracted service goes down for ninety seconds with no timeout and no circuit breaker anywhere in its callers -- and ninety seconds becomes a citywide, fifteen-minute outage.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be24-1', 'campaign-be24', 'the-retry-trap', 'The Retry Trap', 'Partial failure, timeouts, and the retry logic that looks safe right up until it multiplies the exact disaster it was meant to prevent.', 1),
  ('operation-be24-2', 'campaign-be24', 'containing-the-blast', 'Containing the Blast', 'Circuit breakers, bulkheads, load shedding, backpressure and graceful degradation -- the safeguards that keep one failure from becoming everyone''s failure.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be24-01', 'world-be-24', 'campaign-be24', 'operation-be24-1', 'partial-failure', 'Partial Failure', 'One newly-extracted service goes down for ninety seconds. On its own, that should have been nothing at all.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"partial-failure-sim"}'::jsonb, '{"xp":280,"credits":54}'::jsonb, false, 1),
  ('mission-be24-02', 'world-be-24', 'campaign-be24', 'operation-be24-1', 'timeouts', 'Timeouts', 'A call with nothing to bound it will wait forever. Forever is exactly how long a synchronous caller waited during the incident.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be24-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"timeout-config-sim"}'::jsonb, '{"xp":282,"credits":54}'::jsonb, false, 2),
  ('mission-be24-03', 'world-be-24', 'campaign-be24', 'operation-be24-1', 'retry-safety', 'Retry Safety', 'A retry looks like the safe, obvious fix for a failed call -- until the call it''s retrying was never safe to run twice.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be24-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"retry-safety-sim"}'::jsonb, '{"xp":284,"credits":55}'::jsonb, false, 3),
  ('mission-be24-04', 'world-be-24', 'campaign-be24', 'operation-be24-1', 'exponential-backoff', 'Exponential Backoff', 'Retrying immediately just means failing immediately, again and again. Spacing retries out is the first real fix -- if the spacing actually grows.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be24-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"exponential-backoff-sim"}'::jsonb, '{"xp":286,"credits":55}'::jsonb, false, 4),
  ('mission-be24-05', 'world-be-24', 'campaign-be24', 'operation-be24-1', 'jitter', 'Jitter', 'Every client backing off on the exact same schedule still means every client retrying at the exact same instant. Jitter breaks that up.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be24-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"jitter-sim"}'::jsonb, '{"xp":288,"credits":55}'::jsonb, false, 5),
  ('mission-be24-06', 'world-be-24', 'campaign-be24', 'operation-be24-1', 'retry-storms', 'Retry Storms', 'The moment fulfillment-status came back online, every backed-up caller hit it again at once -- and recovery nearly became a second outage.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be24-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"retry-storm-sim"}'::jsonb, '{"xp":290,"credits":56}'::jsonb, false, 6),
  ('mission-be24-07', 'world-be-24', 'campaign-be24', 'operation-be24-2', 'circuit-breakers', 'Circuit Breakers', 'At some point, retrying a failing dependency stops being hopeful and starts being the thing keeping it down. A circuit breaker knows when to stop asking.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be24-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"circuit-breaker-sim"}'::jsonb, '{"xp":292,"credits":56}'::jsonb, false, 7),
  ('mission-be24-08', 'world-be-24', 'campaign-be24', 'operation-be24-2', 'bulkheads', 'Bulkheads', 'One failing dependency shouldn''t be able to starve every other request sharing its connection pool. A bulkhead makes sure it can''t.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be24-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"bulkhead-sim"}'::jsonb, '{"xp":294,"credits":56}'::jsonb, false, 8),
  ('mission-be24-09', 'world-be-24', 'campaign-be24', 'operation-be24-2', 'load-shedding', 'Load Shedding', 'When there is more work than the system can actually do, accepting all of it anyway doesn''t save anyone. Rejecting some of it, fast and on purpose, does.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be24-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"load-shedding-sim"}'::jsonb, '{"xp":296,"credits":57}'::jsonb, false, 9),
  ('mission-be24-10', 'world-be-24', 'campaign-be24', 'operation-be24-2', 'backpressure', 'Backpressure', 'A queue with no limit doesn''t protect anything -- it just moves the crash further downstream and delays it. Backpressure tells upstream to slow down before that happens.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be24-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"backpressure-sim"}'::jsonb, '{"xp":298,"credits":57}'::jsonb, false, 10),
  ('mission-be24-11', 'world-be-24', 'campaign-be24', 'operation-be24-2', 'graceful-degradation', 'Graceful Degradation', 'Not every dependency deserves the power to take down the whole request. Some failures should shrink the page. Others should still stop it cold.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be24-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"graceful-degradation-sim"}'::jsonb, '{"xp":300,"credits":58}'::jsonb, false, 11),
  ('mission-be24-12', 'world-be-24', 'campaign-be24', 'operation-be24-2', 'cascade', 'Cascade', 'Ninety seconds of downtime became a citywide, fifteen-minute outage. Every safeguard this Act taught, aimed at the exact chain that let it happen.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be24-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"cascade-boss-sim"}'::jsonb, '{"xp":640,"credits":150,"badgeIds":["cascade"],"skillXp":{"resilience_engineering":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be24-01', 1, 'mira', 'Act 23 gave us real service boundaries. Real boundaries mean real, independent failure -- and we just found out the hard way that we hadn''t actually planned for that part.'),
  ('mission-be24-01', 2, 'forge', 'fulfillment-status, one of the newest extractions, went down for ninety seconds. On its own, in isolation, that''s a non-event. It did not stay in isolation.'),
  ('mission-be24-01', 3, 'mira', 'Partial failure isn''t a bug. It''s the normal, permanent condition of any system with more than one moving part. The question was never whether something would fail -- it was whether the rest of the system would notice, or just fall in after it.'),

  ('mission-be24-02', 1, 'forge', 'Here''s the first thing that turned ninety seconds into fifteen minutes: every service calling fulfillment-status was calling it synchronously, and not one of those calls had a timeout configured.'),
  ('mission-be24-02', 2, 'forge', 'No timeout means no upper bound on the wait. The thread, the connection, whatever resource made that call -- it just sits there, held, for as long as the other side takes to answer. Or doesn''t.'),

  ('mission-be24-03', 1, 'mira', 'The obvious next fix is "just retry it." Obvious, and not always true. Some calls are perfectly safe to run twice. Some very much are not.'),
  ('mission-be24-03', 2, 'mira', 'The difference has a name: idempotency. Whether running the same call twice leaves the system in the same state as running it once. Get that wrong and your safety net starts causing the damage.'),

  ('mission-be24-04', 1, 'forge', 'Fine -- some calls are safe to retry. Retrying instantly, over and over, is still a bad idea. It just fails faster, more times, against a dependency that is already struggling.'),
  ('mission-be24-04', 2, 'forge', 'Exponential backoff is the standard fix: wait a little after the first failure, wait longer after the second, longer still after the third. Give the other side room to actually recover.'),

  ('mission-be24-05', 1, 'mira', 'Backoff alone has a quiet flaw. If every client that failed at the same moment computes the exact same delay schedule, they all retry at the exact same moment too -- synchronized, not staggered.'),
  ('mission-be24-05', 2, 'mira', 'Jitter is the fix: add a little randomness to each delay so a crowd of clients that failed together doesn''t also recover together, all at once, on the exact dependency that just came back up.'),

  ('mission-be24-06', 1, 'forge', 'This is the part of the incident timeline that actually did the real damage. The moment fulfillment-status came back online, every single backed-up caller hit it again, in the same second.'),
  ('mission-be24-06', 2, 'forge', 'A service coming back from an outage is, for a moment, the most fragile it will ever be. A retry storm at exactly that moment can re-crash it -- and that''s close to what nearly happened here.'),

  ('mission-be24-07', 1, 'mira', 'At some point, retrying a dependency that keeps failing stops being optimism and starts being the reason it can''t recover. A circuit breaker is what notices that point and stops asking.'),
  ('mission-be24-07', 2, 'mira', 'Closed, open, half-open. Learn all three states before you learn where this incident''s breaker should have been and wasn''t.'),

  ('mission-be24-08', 1, 'forge', 'Separate problem, same incident. fulfillment-status and an unrelated service shared one connection pool. When fulfillment-status hung, it didn''t just hurt itself -- it starved every other call standing in line behind it for a connection.'),
  ('mission-be24-08', 2, 'forge', 'A bulkhead is the fix: give each dependency its own isolated slice of resources, so one of them drowning doesn''t sink the whole ship.'),

  ('mission-be24-09', 1, 'mira', 'Different angle entirely: what do you do when there is simply more incoming work than the system can actually handle, dependency failures aside?'),
  ('mission-be24-09', 2, 'mira', 'Load shedding''s answer is blunt, and it turns out correct: reject some of it, deliberately and fast, so the requests you do accept can actually be served properly.'),

  ('mission-be24-10', 1, 'forge', 'Load shedding rejects work at the front door. Backpressure is quieter -- it''s the signal that tells whoever''s producing work to just slow down, before a queue between two internal components grows into something that eats all your memory.'),
  ('mission-be24-10', 2, 'forge', 'One of our internal queues did exactly that during the incident. Nobody was rejecting requests outright. Nobody was signaling upstream to slow down either. It just grew.'),

  ('mission-be24-11', 1, 'mira', 'Last piece before the incident itself: not every failing dependency deserves the power to take the whole request down with it.'),
  ('mission-be24-11', 2, 'mira', 'Graceful degradation asks, honestly, for each dependency: if this fails, should the request fail completely, or should it just get a little smaller and keep going?'),

  ('mission-be24-12', 1, 'mira', 'Leadership actually noticed this one. fulfillment-status went down. Ninety seconds. That should have been a footnote.'),
  ('mission-be24-12', 2, 'forge', 'Instead it took the whole city down for fifteen minutes. Every service that called fulfillment-status synchronously kept calling it, kept waiting, kept hammering it the second it came back -- and none of that had to happen.'),
  ('mission-be24-12', 3, 'mira', 'I have three explanations on the table for how ninety seconds became fifteen minutes. Judge each one on whether it actually explains the shape of the cascade, not just whether it sounds like the kind of thing that''s usually true.'),
  ('mission-be24-12', 4, 'forge', '...one more thing, while you work through those. Pulling the incident timeline turned up something that has nothing to do with today''s fix.'),
  ('mission-be24-12', 5, 'forge', 'A decommissioned internal wiki page. Barely indexed, half the links dead. It references some old reliability-research initiative, shut down years ago from the look of it. Every field with its actual name in it is corrupted except one, and that one still renders as a single, unbroken double slash. Nothing else. No description, no team listed, no reason given for why it was shut down.'),
  ('mission-be24-12', 6, 'mira', 'Nobody currently at Forge has ever heard of it. I checked. Filed, same as every other mark like it -- we still don''t know what any of this was, and today isn''t the day we find out.'),
  ('mission-be24-12', 7, 'forge', 'For today: three explanations, one real chain of missing safeguards. Find it. The system survives failure now -- next we stop finding that out after the fact and start watching it happen, live.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be24-01-o1', 'mission-be24-01', 1, 'Define the failure', 'Decide what "partial failure" actually means for a system built out of independent services.'),
  ('mission-be24-01-o2', 'mission-be24-01', 2, 'Find the failure boundary', 'Find the evidence that shows the outage didn''t stay contained to the one service that broke.'),
  ('mission-be24-02-o1', 'mission-be24-02', 1, 'Name what a timeout protects', 'Decide what a timeout actually bounds when a dependency stops responding.'),
  ('mission-be24-02-o2', 'mission-be24-02', 2, 'Find the missing timeout', 'Find the call that was left with no bound on how long it would wait.'),
  ('mission-be24-03-o1', 'mission-be24-03', 1, 'Sort safe from unsafe retries', 'Decide which operations are safe to retry blindly and which are not.'),
  ('mission-be24-03-o2', 'mission-be24-03', 2, 'Trace the duplicate side effect', 'Find the evidence that explains why a retried call left the system in the wrong state.'),
  ('mission-be24-04-o1', 'mission-be24-04', 1, 'Order a real backoff schedule', 'Put the stages of a well-behaved exponential backoff in order.'),
  ('mission-be24-04-o2', 'mission-be24-04', 2, 'Find the backoff bug', 'Find the line that keeps this retry helper from actually backing off exponentially.'),
  ('mission-be24-05-o1', 'mission-be24-05', 1, 'Explain the synchronized retry', 'Decide what happens when many clients compute the exact same backoff schedule.'),
  ('mission-be24-05-o2', 'mission-be24-05', 2, 'Find the missing jitter', 'Find the line where randomness should have been added before the delay was used.'),
  ('mission-be24-06-o1', 'mission-be24-06', 1, 'Diagnose the recovery spike', 'Find the evidence that explains why traffic arrived as one synchronized spike instead of a gradual ramp.'),
  ('mission-be24-06-o2', 'mission-be24-06', 2, 'Name the real fix', 'Decide which combination of safeguards would have actually prevented the synchronized spike.'),
  ('mission-be24-07-o1', 'mission-be24-07', 1, 'Order the circuit breaker states', 'Put the lifecycle of a circuit breaker in order, from healthy to tripped to tested.'),
  ('mission-be24-07-o2', 'mission-be24-07', 2, 'Find the skipped trial phase', 'Find the line that lets the breaker skip straight from open to closed with no trial.'),
  ('mission-be24-08-o1', 'mission-be24-08', 1, 'Name what a bulkhead protects', 'Decide what a bulkhead actually isolates a failing dependency from.'),
  ('mission-be24-08-o2', 'mission-be24-08', 2, 'Trace the starved caller', 'Find the evidence that shows the failure spread to a service that was never actually broken.'),
  ('mission-be24-09-o1', 'mission-be24-09', 1, 'Define load shedding', 'Decide what load shedding actually does when demand exceeds capacity.'),
  ('mission-be24-09-o2', 'mission-be24-09', 2, 'Find the missing shed check', 'Find the line missing the check that should have rejected work once the queue was already full.'),
  ('mission-be24-10-o1', 'mission-be24-10', 1, 'Tell the safeguards apart', 'Match circuit breakers, bulkheads, load shedding and backpressure to what each one actually does.'),
  ('mission-be24-10-o2', 'mission-be24-10', 2, 'Trace the unbounded queue', 'Find the evidence that shows the missing safeguard was about the queue''s growth, not the workers behind it.'),
  ('mission-be24-11-o1', 'mission-be24-11', 1, 'Judge the degraded response', 'Decide what a non-critical dependency failing should actually do to the rest of the request.'),
  ('mission-be24-11-o2', 'mission-be24-11', 2, 'Spot the dependency that should not degrade', 'Find the evidence that shows the system correctly refused to degrade gracefully for something that actually mattered.'),
  ('mission-be24-12-o1', 'mission-be24-12', 1, 'Diagnosis: No Timeouts', 'Judge whether the missing-timeouts explanation actually accounts for the cascade.'),
  ('mission-be24-12-o2', 'mission-be24-12', 2, 'Diagnosis: No Circuit Breaker', 'Judge whether the missing-circuit-breaker explanation actually accounts for the cascade.'),
  ('mission-be24-12-o3', 'mission-be24-12', 3, 'Diagnosis: The Recovery Storm', 'Find the evidence that explains why every retry landed in the same instant.'),
  ('mission-be24-12-o4', 'mission-be24-12', 4, 'Fix the Cascade', 'State the combination of safeguards that would have kept ninety seconds from becoming fifteen minutes.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be24-01-o1-c1', 'mission-be24-01-o1', 1, 'multiple_choice', 'The newly-extracted service went down for ninety seconds. What does "partial failure" actually describe about a distributed system?', '{"question":"The newly-extracted service went down for ninety seconds. What does \"partial failure\" actually describe about a distributed system?","options":[{"id":"a","text":"One dependency is unavailable while the rest of the system keeps running -- and every caller has to decide, on its own, what that means for it"},{"id":"b","text":"The entire system goes down at once, so there is nothing partial about it"},{"id":"c","text":"A service that intermittently returns 500 errors is not actually failing, just slow"},{"id":"d","text":"Partial failure only applies to hardware, never to services"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be24-01-o2-c1', 'mission-be24-01-o2', 1, 'investigation', 'Which piece of evidence shows the failure didn''t stay contained to the one service that actually broke?', '{"evidence":[{"id":"ev1","label":"Incident timeline","detail":"fulfillment-status returned no response for 90 seconds starting at 14:02:11"},{"id":"ev2","label":"Caller behavior","detail":"Every service that called fulfillment-status synchronously, with no timeout, was still waiting on that call at 14:03:41 -- ninety seconds later"},{"id":"ev3","label":"Unrelated service","detail":"The notifications service, which never calls fulfillment-status, kept operating normally throughout"}],"question":"Which piece of evidence shows the failure didn''t stay contained to the one service that actually broke?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be24-02-o1-c1', 'mission-be24-02-o1', 1, 'multiple_choice', 'A call with no timeout is waiting on the failing fulfillment-status service. What is actually happening to the thread or connection holding that call?', '{"question":"A call with no timeout is waiting on the failing fulfillment-status service. What is actually happening to the thread or connection holding that call?","options":[{"id":"a","text":"It''s held open indefinitely, unable to do anything else, until the far side finally answers or the process is restarted"},{"id":"b","text":"It automatically fails after a sensible default the operating system provides"},{"id":"c","text":"It''s fine, since only the response body is delayed, not the connection itself"},{"id":"d","text":"The call silently retries itself in the background with no code required"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be24-02-o2-c1', 'mission-be24-02-o2', 1, 'code_debugging', 'getInventoryLevel hung for six minutes during the incident while getPricingTier failed fast and let its caller move on. Which line is missing the safeguard that would have bounded the wait?', '{"language":"typescript","code":"async function getInventoryLevel(warehouseId) {\n  const response = await httpClient.get(\"/warehouses/\" + warehouseId + \"/inventory\");\n  return response.data.level;\n}\n\nasync function getPricingTier(customerId) {\n  const response = await httpClient.get(\"/pricing/\" + customerId, { timeout: 3000 });\n  return response.data.tier;\n}","question":"getInventoryLevel hung for six minutes during the incident while getPricingTier failed fast and let its caller move on. Which line is missing the safeguard that would have bounded the wait?"}'::jsonb, '{"requiredLineIds":["  const response = await httpClient.get(\"/warehouses/\" + warehouseId + \"/inventory\");"]}'::jsonb),

  ('mission-be24-03-o1-c1', 'mission-be24-03-o1', 1, 'drag_and_drop', 'Sort each operation by whether it is safe to retry blindly.', '{"items":[{"id":"i1","text":"GET /shipments/{id}/status"},{"id":"i2","text":"POST /payments/charge"},{"id":"i3","text":"PUT /inventory/{sku}/reserve (sets the reserved count to an exact value)"},{"id":"i4","text":"POST /inventory/{sku}/increment (adds 1 to the current count)"}],"targets":[{"id":"t1","label":"Safe to retry -- same call, same result, no matter how many times it runs"},{"id":"t2","label":"Unsafe to retry blindly -- could duplicate a real-world side effect"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),
  ('mission-be24-03-o2-c1', 'mission-be24-03-o2', 1, 'investigation', 'Which piece of evidence explains why the inventory count ended up wrong, not just why a retry happened?', '{"evidence":[{"id":"ev1","label":"Retry log","detail":"The increment call for SKU AX-410 was retried three times after a timeout, and the stock count went up by 3 instead of 1"},{"id":"ev2","label":"Client code","detail":"The retry wrapper treats every failed call the same way, regardless of which endpoint it is calling"},{"id":"ev3","label":"Network trace","detail":"The first two attempts actually succeeded on the server before the client ever saw a response, timing out only on its own end"}],"question":"Which piece of evidence explains why the inventory count ended up wrong, not just why a retry happened?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be24-04-o1-c1', 'mission-be24-04-o1', 1, 'interactive_diagram', 'Put the stages of a well-behaved exponential backoff in order.', '{"diagramId":"exponential-backoff-lifecycle","hotspots":[{"id":"attempt_fails","label":"First attempt fails","explanation":"The call to the dependency does not succeed."},{"id":"short_wait","label":"Client waits a short base delay","explanation":"Instead of retrying instantly, the client pauses briefly first."},{"id":"retry_again","label":"Client retries","explanation":"A new attempt is made after the delay."},{"id":"delay_doubles","label":"On repeated failure, the delay roughly doubles each time","explanation":"Each subsequent failure grows the wait, giving the dependency more room to recover."},{"id":"delay_capped","label":"The delay is capped at a maximum","explanation":"Growth stops at a sane ceiling instead of climbing forever."}],"task":"Put the stages of a well-behaved exponential backoff in order."}'::jsonb, '{"correctOrderIds":["attempt_fails","short_wait","retry_again","delay_doubles","delay_capped"]}'::jsonb),
  ('mission-be24-04-o2-c1', 'mission-be24-04-o2', 1, 'code_debugging', 'This retry helper was supposed to back off exponentially, but during the incident retries barely slowed down at all as failures piled up. Which line is the bug?', '{"language":"typescript","code":"function getRetryDelayMs(attempt) {\n  const base = 200;\n  const delay = base * attempt;\n  return delay;\n}","question":"This retry helper was supposed to back off exponentially, but during the incident retries barely slowed down at all as failures piled up. Which line is the bug?"}'::jsonb, '{"requiredLineIds":["  const delay = base * attempt;"]}'::jsonb),

  ('mission-be24-05-o1-c1', 'mission-be24-05-o1', 1, 'multiple_choice', 'A backoff schedule is working exactly as designed: every client computes 200ms, then 400ms, then 800ms delays, deterministically. Hundreds of clients that all failed at the same moment now all retry at...', '{"question":"A backoff schedule is working exactly as designed: every client computes 200ms, then 400ms, then 800ms delays, deterministically. Hundreds of clients that all failed at the same moment now all retry at...","options":[{"id":"a","text":"different, randomly spread times -- so the recovering service sees a manageable trickle of traffic"},{"id":"b","text":"the exact same moment as each other, over and over, because the schedule is deterministic and every client started failing together"},{"id":"c","text":"no particular pattern, since backoff already accounts for this"},{"id":"d","text":"a rate the recovering service can always absorb, because exponential growth guarantees it"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be24-05-o2-c1', 'mission-be24-05-o2', 1, 'code_debugging', 'The exponential growth and the cap are both correct here, and hundreds of clients that failed at the same instant still all retried at the same instant, over and over. Which line is missing the piece that should have spread them apart?', '{"language":"typescript","code":"function getRetryDelayMs(attempt) {\n  const base = 200;\n  const maxDelay = 30000;\n  const delay = Math.min(base * Math.pow(2, attempt), maxDelay);\n  return delay;\n}","question":"The exponential growth and the cap are both correct here, and hundreds of clients that failed at the same instant still all retried at the same instant, over and over. Which line is missing the piece that should have spread them apart?"}'::jsonb, '{"requiredLineIds":["  return delay;"]}'::jsonb),

  ('mission-be24-06-o1-c1', 'mission-be24-06-o1', 1, 'investigation', 'Which piece of evidence explains why traffic arrived as one synchronized spike instead of a gradual ramp?', '{"evidence":[{"id":"ev1","label":"Recovery timestamp","detail":"fulfillment-status came back online at 14:03:41"},{"id":"ev2","label":"Traffic spike","detail":"Inbound request volume to fulfillment-status jumped from 0 to over 12,000 requests in the same second it came back"},{"id":"ev3","label":"Retry config","detail":"Every caller was retrying on a fixed 1-second interval, with no backoff and no jitter, since the moment the first call failed"}],"question":"Which piece of evidence explains why traffic arrived as one synchronized spike instead of a gradual ramp?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be24-06-o2-c1', 'mission-be24-06-o2', 1, 'multiple_choice', 'Which combination of safeguards would have actually prevented that synchronized spike, rather than just making individual retries look nicer?', '{"question":"Which combination of safeguards would have actually prevented that synchronized spike, rather than just making individual retries look nicer?","options":[{"id":"a","text":"A longer fixed retry interval, alone"},{"id":"b","text":"Exponential backoff with jitter, so retries spread out over time instead of all landing on the same instant"},{"id":"c","text":"Retrying twice as fast so recovery is detected sooner"},{"id":"d","text":"Logging every retry attempt in more detail for later review"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be24-07-o1-c1', 'mission-be24-07-o1', 1, 'interactive_diagram', 'Put the lifecycle of a circuit breaker in order.', '{"diagramId":"circuit-breaker-lifecycle","hotspots":[{"id":"closed","label":"Circuit is closed","explanation":"The normal state -- calls pass straight through to the dependency, and failures are counted."},{"id":"threshold_exceeded","label":"Failure count crosses the threshold","explanation":"Enough recent calls have failed that the breaker decides the dependency is actually down."},{"id":"open","label":"Circuit opens","explanation":"Calls fail immediately, without ever reaching the struggling dependency, giving it room to recover."},{"id":"timeout_elapses","label":"Reset timeout elapses","explanation":"After a pause, the breaker is willing to find out whether the dependency has recovered."},{"id":"half_open","label":"Circuit goes half-open","explanation":"A small number of trial requests are let through to test the dependency, instead of the full traffic volume."},{"id":"closed_again","label":"A successful trial closes the circuit again","explanation":"Only real proof of recovery -- not just time passing -- restores full traffic."}],"task":"Put the lifecycle of a circuit breaker in order."}'::jsonb, '{"correctOrderIds":["closed","threshold_exceeded","open","timeout_elapses","half_open","closed_again"]}'::jsonb),
  ('mission-be24-07-o2-c1', 'mission-be24-07-o2', 1, 'code_debugging', 'After the reset timeout passes, this breaker lets the full, normal volume of traffic straight back through in one step. Which line is the bug that skipped the trial phase entirely?', '{"language":"typescript","code":"function shouldAllowRequest(breaker, now) {\n  if (breaker.state === \"closed\") return true;\n  if (breaker.state === \"open\" && now - breaker.openedAt > breaker.resetTimeoutMs) {\n    breaker.state = \"closed\";\n  }\n  return breaker.state === \"closed\";\n}","question":"After the reset timeout passes, this breaker lets the full, normal volume of traffic straight back through in one step. Which line is the bug that skipped the trial phase entirely?"}'::jsonb, '{"requiredLineIds":["    breaker.state = \"closed\";"]}'::jsonb),

  ('mission-be24-08-o1-c1', 'mission-be24-08-o1', 1, 'multiple_choice', 'fulfillment-status and the notifications service share the same connection pool. When fulfillment-status started hanging, what did the bulkhead pattern -- had it existed -- actually protect against?', '{"question":"fulfillment-status and the notifications service share the same connection pool. When fulfillment-status started hanging, what did the bulkhead pattern -- had it existed -- actually protect against?","options":[{"id":"a","text":"The failing dependency exhausting a shared resource pool and starving unrelated calls that had nothing to do with it"},{"id":"b","text":"The failing dependency returning the wrong data"},{"id":"c","text":"The need for retries entirely"},{"id":"d","text":"Ordinary network latency between two healthy services"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be24-08-o2-c1', 'mission-be24-08-o2', 1, 'investigation', 'Which piece of evidence shows the failure spread to a service that was never actually broken?', '{"evidence":[{"id":"ev1","label":"Pool metrics","detail":"The shared HTTP connection pool (max 50 connections) had all 50 slots held by calls to fulfillment-status"},{"id":"ev2","label":"Unrelated caller","detail":"A request to the notifications service failed with \"no available connection\" despite notifications itself being perfectly healthy"},{"id":"ev3","label":"Dependency status","detail":"fulfillment-status itself was still down at the time of both failures"}],"question":"Which piece of evidence shows the failure spread to a service that was never actually broken?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be24-09-o1-c1', 'mission-be24-09-o1', 1, 'multiple_choice', 'Under the traffic spike, the server has far more incoming requests than it can actually process. What does load shedding do about that?', '{"question":"Under the traffic spike, the server has far more incoming requests than it can actually process. What does load shedding do about that?","options":[{"id":"a","text":"Deliberately rejects some requests up front, fast and cheap, so the ones it does accept can still be served properly"},{"id":"b","text":"Queues every request indefinitely so nothing is ever rejected"},{"id":"c","text":"Slows down every request equally so none of them ever fail"},{"id":"d","text":"Automatically spins up more servers instantly with zero delay"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be24-09-o2-c1', 'mission-be24-09-o2', 1, 'code_debugging', 'During the incident this queue grew past forty thousand pending requests instead of ever turning new ones away. Which line is missing the check that should have shed load once the queue was already full?', '{"language":"typescript","code":"function handleIncomingRequest(queue, request) {\n  queue.push(request);\n  processNext(queue);\n}","question":"During the incident this queue grew past forty thousand pending requests instead of ever turning new ones away. Which line is missing the check that should have shed load once the queue was already full?"}'::jsonb, '{"requiredLineIds":["  queue.push(request);"]}'::jsonb),

  ('mission-be24-10-o1-c1', 'mission-be24-10-o1', 1, 'drag_and_drop', 'Match each safeguard to what it actually does.', '{"items":[{"id":"i1","text":"Circuit breaker"},{"id":"i2","text":"Bulkhead"},{"id":"i3","text":"Load shedding"},{"id":"i4","text":"Backpressure"}],"targets":[{"id":"t1","label":"Stops calling a specific dependency entirely once it is clearly failing"},{"id":"t2","label":"Isolates a resource pool per dependency so one failing dependency can''t starve the others"},{"id":"t3","label":"Rejects excess work outright once capacity is exceeded, rather than accepting it and failing later"},{"id":"t4","label":"Signals upstream to slow down production of new work before a queue grows unbounded"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-be24-10-o2-c1', 'mission-be24-10-o2', 1, 'investigation', 'Which piece of evidence shows the missing safeguard was about the queue''s growth, not the workers behind it?', '{"evidence":[{"id":"ev1","label":"Queue metrics","detail":"The internal work queue between the API layer and the fulfillment worker pool grew from a few hundred items to over 200,000 during the incident, with no upper bound configured"},{"id":"ev2","label":"Memory graph","detail":"Memory usage on the API layer climbed steadily until the process was killed by the OS for running out of memory"},{"id":"ev3","label":"Worker pool","detail":"The fulfillment worker pool itself never crashed -- it just fell further and further behind"}],"question":"Which piece of evidence shows the missing safeguard was about the queue''s growth, not the workers behind it?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be24-11-o1-c1', 'mission-be24-11-o1', 1, 'multiple_choice', 'A product page also calls a "related items" recommendation service that is currently down. What does graceful degradation say the product page should do?', '{"question":"A product page also calls a \"related items\" recommendation service that is currently down. What does graceful degradation say the product page should do?","options":[{"id":"a","text":"Fail the entire page load, since one dependency failed"},{"id":"b","text":"Serve the core product page -- price, stock, the buy button -- without the recommendations section, instead of failing the whole request over a non-critical dependency"},{"id":"c","text":"Retry the recommendation call forever until it succeeds"},{"id":"d","text":"Show a generic error page for every request regardless of which dependency failed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be24-11-o2-c1', 'mission-be24-11-o2', 1, 'investigation', 'Which piece of evidence shows the system correctly identified something as critical enough that it should NOT degrade gracefully?', '{"evidence":[{"id":"ev1","label":"Product page incident","detail":"When the recommendations service went down, the product page still rendered price, stock and the buy button correctly for every user"},{"id":"ev2","label":"Checkout incident","detail":"When the payments service went down, checkout correctly failed outright rather than pretending to accept an order it couldn''t charge for"},{"id":"ev3","label":"Recommendations code","detail":"The recommendations section was wrapped in its own error boundary with a fallback of \"no items to show\""}],"question":"Which piece of evidence shows the system correctly identified something as critical enough that it should NOT degrade gracefully?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be24-12-o1-c1', 'mission-be24-12-o1', 1, 'multiple_choice', 'Every caller of fulfillment-status was still blocked on that same call ninety seconds after it went down. What safeguard, if it had existed, would have kept those callers from backing up in the first place?', '{"question":"Every caller of fulfillment-status was still blocked on that same call ninety seconds after it went down. What safeguard, if it had existed, would have kept those callers from backing up in the first place?","options":[{"id":"a","text":"A timeout on the outbound call, so each caller gave up and freed its thread or connection after a bounded wait instead of hanging indefinitely"},{"id":"b","text":"A bigger database"},{"id":"c","text":"A faster network link between datacenters"},{"id":"d","text":"More application servers handling the same synchronous calls"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be24-12-o2-c1', 'mission-be24-12-o2', 1, 'multiple_choice', 'Even after the first few calls to fulfillment-status started failing, every subsequent request kept trying it again, immediately, for the full ninety seconds. What safeguard would have stopped that repeated hammering of a service everyone had already seen fail?', '{"question":"Even after the first few calls to fulfillment-status started failing, every subsequent request kept trying it again, immediately, for the full ninety seconds. What safeguard would have stopped that repeated hammering of a service everyone had already seen fail?","options":[{"id":"a","text":"A circuit breaker that opened after enough failures and started failing calls immediately, without ever reaching the dependency, until it looked safe to try again"},{"id":"b","text":"A larger connection pool"},{"id":"c","text":"Logging every failed call in more detail"},{"id":"d","text":"A faster DNS resolver"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be24-12-o3-c1', 'mission-be24-12-o3', 1, 'investigation', 'Which piece of evidence explains why the retries all landed in the same instant instead of gradually?', '{"evidence":[{"id":"ev1","label":"Recovery trace","detail":"The instant fulfillment-status came back online, every backed-up caller''s next scheduled retry fired within the same one-second window"},{"id":"ev2","label":"Retry config audit","detail":"Every caller was retrying on a fixed, non-randomized interval with no backoff, so failures that started together stayed synchronized the entire time"},{"id":"ev3","label":"Post-recovery crash","detail":"fulfillment-status fell back over within seconds of coming back up, under the exact traffic spike caused by that synchronized retry"}],"question":"Which piece of evidence explains why the retries all landed in the same instant instead of gradually?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be24-12-o4-c1', 'mission-be24-12-o4', 1, 'boss_encounter', 'Having diagnosed all three, state the combination of safeguards that would have kept ninety seconds of downtime from ever becoming a citywide outage.', '{"stages":[{"objectiveRef":"mission-be24-12-o1","label":"Diagnosis: No Timeouts"},{"objectiveRef":"mission-be24-12-o2","label":"Diagnosis: No Circuit Breaker"},{"objectiveRef":"mission-be24-12-o3","label":"Diagnosis: The Recovery Storm"}],"task":"Having diagnosed all three, state the combination of safeguards that would have kept ninety seconds of downtime from ever becoming a citywide outage: timeouts so callers never hung indefinitely, a circuit breaker so repeated failures stopped being retried immediately, and backoff with jitter so the recovering service wasn''t immediately re-hammered by every caller at once."}'::jsonb, '{"requiredObjectiveIds":["mission-be24-12-o1","mission-be24-12-o2","mission-be24-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be24-01-o1-c1', 'orientation', 'Think about what the rest of the system is supposed to be able to do while one piece of it is down.', 10, 1),
  ('mission-be24-01-o1-c1', 'solution', 'a -- partial failure means one dependency is out while the rest keep running, and every caller has to decide for itself what that means.', 20, 2),
  ('mission-be24-01-o2-c1', 'orientation', 'Two of these entries describe things that stayed healthy. One describes something that stopped being healthy for a reason that had nothing to do with its own code.', 10, 1),
  ('mission-be24-01-o2-c1', 'solution', 'ev2 -- callers with no timeout were still stuck waiting ninety seconds later, which is the failure spreading beyond the one broken service.', 20, 2),

  ('mission-be24-02-o1-c1', 'orientation', 'Ask what a "wait" without a limit actually costs the caller, not the dependency.', 10, 1),
  ('mission-be24-02-o1-c1', 'solution', 'a -- with no timeout, the resource making the call is held open for as long as the other side takes, with no guaranteed ceiling.', 20, 2),
  ('mission-be24-02-o2-c1', 'orientation', 'Compare the two calls line by line -- one of them passes an extra option the other one doesn''t.', 10, 1),
  ('mission-be24-02-o2-c1', 'concept', 'A timeout has to be configured explicitly on most HTTP clients; nothing bounds the wait by default.', 20, 2),
  ('mission-be24-02-o2-c1', 'solution', 'getInventoryLevel''s call has no timeout option at all, unlike getPricingTier''s { timeout: 3000 } -- that missing option is why it hung indefinitely.', 30, 3),

  ('mission-be24-03-o1-c1', 'orientation', 'Ask, for each one: if this exact call ran twice by accident, would the system end up any different than if it ran once?', 10, 1),
  ('mission-be24-03-o1-c1', 'solution', 'GET and "set to an exact value" are idempotent (safe). A charge and an increment both change state further each time they run (unsafe).', 20, 2),
  ('mission-be24-03-o2-c1', 'orientation', 'The retry itself isn''t the bug -- what the retried call actually does to state is.', 10, 1),
  ('mission-be24-03-o2-c1', 'solution', 'ev1 -- the increment endpoint was retried three times and the count went up by 3, which is exactly what happens when a non-idempotent call gets retried blindly.', 20, 2),

  ('mission-be24-04-o1-c1', 'orientation', 'Nothing can double a delay that hasn''t happened once already.', 10, 1),
  ('mission-be24-04-o1-c1', 'solution', 'Attempt fails, wait a short delay, retry, the delay roughly doubles on further failures, and it is capped at a maximum.', 20, 2),
  ('mission-be24-04-o2-c1', 'orientation', 'Exponential growth means multiplying by a growing factor each time, not multiplying by the attempt number.', 10, 1),
  ('mission-be24-04-o2-c1', 'concept', 'base * attempt grows linearly (200, 400, 600...); exponential backoff needs base * 2^attempt (200, 400, 800, 1600...).', 20, 2),
  ('mission-be24-04-o2-c1', 'solution', 'const delay = base * attempt; is linear growth dressed up as backoff -- it should be base * Math.pow(2, attempt), capped at a maximum.', 30, 3),

  ('mission-be24-05-o1-c1', 'orientation', 'Ask what "deterministic" means for hundreds of clients that all started failing at once.', 10, 1),
  ('mission-be24-05-o1-c1', 'solution', 'b -- with no randomness, every client that failed together computes the same schedule and retries together, over and over.', 20, 2),
  ('mission-be24-05-o2-c1', 'orientation', 'The math for exponential growth and the cap are both already correct here -- look at what happens right before the number leaves the function.', 10, 1),
  ('mission-be24-05-o2-c1', 'concept', 'Jitter means adding randomness to the final delay -- commonly a random value between 0 and the computed delay -- right before it is used.', 20, 2),
  ('mission-be24-05-o2-c1', 'solution', 'return delay; returns the deterministic, unmodified value with no randomness ever added -- that''s the missing jitter.', 30, 3),

  ('mission-be24-06-o1-c1', 'orientation', 'Two of these describe what happened. One describes why it happened in that exact shape.', 10, 1),
  ('mission-be24-06-o1-c1', 'solution', 'ev3 -- a fixed interval with no backoff and no jitter means every caller that started failing together stayed on the exact same retry clock the entire time.', 20, 2),
  ('mission-be24-06-o2-c1', 'orientation', 'Think about what actually spreads retries apart in time, not what just changes their frequency.', 10, 1),
  ('mission-be24-06-o2-c1', 'solution', 'b -- backoff with jitter is the only option here that actually staggers when different clients retry, instead of just changing how often or how loudly they all do it together.', 20, 2),

  ('mission-be24-07-o1-c1', 'orientation', 'A trial can''t happen before the breaker has decided enough time has passed to even attempt one.', 10, 1),
  ('mission-be24-07-o1-c1', 'solution', 'Closed, failures cross the threshold, open, the reset timeout elapses, half-open (trial requests), and a successful trial closes it again.', 20, 2),
  ('mission-be24-07-o2-c1', 'orientation', 'Compare this code against the states you just ordered -- one state is completely missing from it.', 10, 1),
  ('mission-be24-07-o2-c1', 'concept', 'A correct breaker moves from open to half-open after the timeout, tests with a small number of requests, and only then closes on real success -- never straight from open to closed.', 20, 2),
  ('mission-be24-07-o2-c1', 'solution', 'breaker.state = "closed"; fires the instant the timeout elapses, skipping the half-open trial entirely and letting full traffic straight through untested.', 30, 3),

  ('mission-be24-08-o1-c1', 'orientation', 'The notifications service never called fulfillment-status at all -- so what connects the two failures?', 10, 1),
  ('mission-be24-08-o1-c1', 'solution', 'a -- a bulkhead isolates resources per dependency so a failure in one can''t exhaust a pool shared with something completely unrelated.', 20, 2),
  ('mission-be24-08-o2-c1', 'orientation', 'Look for the entry that describes a service failing for a reason that has nothing to do with its own health.', 10, 1),
  ('mission-be24-08-o2-c1', 'solution', 'ev2 -- notifications failed with "no available connection" while notifications itself was healthy, because fulfillment-status had taken every slot in the shared pool.', 20, 2),

  ('mission-be24-09-o1-c1', 'orientation', 'Think about what happens to quality of service if every single request is accepted no matter how overloaded the system already is.', 10, 1),
  ('mission-be24-09-o1-c1', 'solution', 'a -- load shedding deliberately rejects some requests up front so the accepted ones can still be handled properly.', 20, 2),
  ('mission-be24-09-o2-c1', 'orientation', 'A queue with no capacity check accepts everything, forever, regardless of how far behind it already is.', 10, 1),
  ('mission-be24-09-o2-c1', 'solution', 'queue.push(request); has no check against queue.length or any capacity limit before accepting -- that missing check is why it grew unbounded instead of shedding load.', 20, 2),

  ('mission-be24-10-o1-c1', 'orientation', 'One of these acts at the front door, one acts between two internal components, one isolates resources, and one stops calling a dependency entirely.', 10, 1),
  ('mission-be24-10-o1-c1', 'solution', 'Circuit breaker -> stops calling a failing dependency. Bulkhead -> isolates resources per dependency. Load shedding -> rejects excess work outright. Backpressure -> signals upstream to slow production.', 20, 2),
  ('mission-be24-10-o2-c1', 'orientation', 'The workers falling behind is a symptom. Look for what actually grew without limit.', 10, 1),
  ('mission-be24-10-o2-c1', 'solution', 'ev1 -- the queue itself grew from a few hundred to over 200,000 items with no upper bound, which is the missing backpressure, not a worker-pool problem.', 20, 2),

  ('mission-be24-11-o1-c1', 'orientation', 'Ask whether recommendations are actually required for the rest of the page to make sense and function.', 10, 1),
  ('mission-be24-11-o1-c1', 'solution', 'b -- the core page (price, stock, buy button) should still work; only the non-critical recommendations section needs to shrink or disappear.', 20, 2),
  ('mission-be24-11-o2-c1', 'orientation', 'Graceful degradation is a choice, not a universal rule -- something in this incident correctly did NOT degrade.', 10, 1),
  ('mission-be24-11-o2-c1', 'concept', 'A request that can''t actually be completed correctly -- like a charge that can''t be processed -- should fail loudly, not pretend to succeed in a smaller form.', 20, 2),
  ('mission-be24-11-o2-c1', 'solution', 'ev2 -- checkout correctly failed outright when payments was down, because silently accepting an order it couldn''t charge for would have been worse than failing.', 30, 3),

  ('mission-be24-12-o1-c1', 'orientation', 'Every caller was still blocked on the same call ninety seconds later -- ask what would have forced them to stop waiting.', 10, 1),
  ('mission-be24-12-o1-c1', 'solution', 'a -- a timeout on the outbound call would have bounded the wait so callers freed their resources instead of hanging indefinitely.', 20, 2),
  ('mission-be24-12-o2-c1', 'orientation', 'The problem here isn''t the first failed call -- it''s every call after it that kept trying anyway.', 10, 1),
  ('mission-be24-12-o2-c1', 'solution', 'a -- a circuit breaker would have stopped sending calls to a dependency everyone already knew was down, instead of hammering it the whole time.', 20, 2),
  ('mission-be24-12-o3-c1', 'orientation', 'Ask what made every caller''s clock line up perfectly at the exact moment of recovery.', 10, 1),
  ('mission-be24-12-o3-c1', 'solution', 'ev2 -- a fixed, non-randomized interval with no backoff kept every caller synchronized from the first failure straight through to the exact moment of recovery.', 20, 2),
  ('mission-be24-12-o4-c1', 'orientation', 'You just diagnosed three separate gaps -- the fix is all three together, not any one alone.', 15, 1),
  ('mission-be24-12-o4-c1', 'solution', 'Timeouts so callers never hung indefinitely, a circuit breaker so repeated failures stopped being retried the instant they were detected, and backoff with jitter so the recovering service wasn''t immediately re-hammered by every caller at once.', 25, 2);
